// page.tsx (Server Component)
export default async function SearchPage({ searchParams }) {
  const listings = await searchListings(searchParams);
  return (
    <>
      <SearchFilters /> {/* client */}
      <ListingGrid listings={listings} /> {/* server */}
    </>
  );
}

